SELECT r.relax_id, r.order_id, r.order_no, r.fabric_id, r.fabric_no, r.fabric_name, r.color_name, r.require_length, r.actual_length, r.relax_hours, r.status, r.remark, r.create_user_name, r.create_time, r.relax_time, r.actual_start_time, r.actual_end_time, o.customer_name FROM t_fabric_relax r LEFT JOIN t_production_order o ON r.order_id = o.order_id
r.deleted_flag = 0
AND INSTR(r.order_no, #{queryForm.orderNo})
AND r.status = #{queryForm.status}
AND r.relax_type = #{queryForm.relaxType}
ORDER BY r.relax_id DESC
